142	  it("hypothetical DI: the premium is [(1 + p)^(DU/252) - 1] over the amount retired, truncated at eight decimals; the 98% amortization never competes as a full exit", () => {
143	    const result = estimateExitCostBySeries(priced());
144	    const base = d("101.5");
145	    const factor = d("1.004").pow(d(504).div(252)).minus(1);
146	    const total = route(result, "h-di", "total_redemption_di");
147	    expect(total.premium).toBe(base.times(factor).toDecimalPlaces(8, Decimal.ROUND_DOWN).toFixed());
148	    expect(total.premium).toBe("0.813624");
149	    expect(total.scope).toBe("full");
150	    const partial = route(result, "h-di", "extraordinary_amortization_di");
151	    expect(partial.scope).toBe("partial");
152	    expect(partial.amount_retired).toBe(base.times("0.98").toFixed());
153	    expect(partial.premium).toBe(base.times("0.98").times(factor).toDecimalPlaces(8, Decimal.ROUND_DOWN).toFixed());
154	    expect(d(partial.total_payable!).lt(total.total_payable!)).toBe(true);
155	    expect(series(result, "h-di").cheapest_full_exit).toEqual({mechanism: "total_redemption_di", total_payable: total.total_payable});
156	    // The offer retires what adhered: 60% of the base at the notice's premium.
157	    expect(route(result, "h-di", "negotiated_offer").amount_retired).toBe(base.times("0.6").toFixed());
158	    expect(route(result, "h-di", "negotiated_offer").premium).toBe(base.times("0.6").times("0.01").toFixed());
159	    expect(route(result, "h-di", "negotiated_offer").fraction).toBe("0.6");
