  7	/**
  8	 * Executor of the method `estimate-exit-cost-by-series` (v6, after the fourth independent review).
  9	 * For each series an alternative wants to retire on a date: which mechanisms its indenture offers on
 10	 * that date, each with its own formula, scope and quote day, and what each costs with what the base
 11	 * holds. The base of any price is the nominal at the exit date (updated where indexed, with the
 12	 * derivation the source allows), the remuneration accrued to that date and the charges the indenture
 13	 * states, each dated at the exit and anchored; a 31/05 balance is not a nominal at 04/09, and a
 14	 * missing component is insufficient evidence, never zero. Mechanisms are never merged: the DI
 15	 * premium is [(1 + p)^(DU/252) - 1] over the amount retired, truncated at eight decimals; an
 16	 * extraordinary amortization retires a fraction the indenture caps and never competes as a full
 17	 * exit; a make-whole redemption discounts the remaining flows at the quote of the contractual day
 18	 * (the prior or the second prior business day, as the series says, and that distance is checked
 19	 * against the calendar), adds the charges the indenture adds, and applies the floor the series says
 20	 * (the updated value, or none); the duration that selects the reference security is discounted at
 21	 * the series' own remuneration; a negotiated offer is open since issuance with a premium to be set;
 22	 * an acquisition depends on the seller and may be partial. Every anchor names a document of the
 23	 * base's registry and every mechanism cites the series' indenture with its clause; a series without
 24	 * an indenture is not priced. Business days are the weekdays less the holidays the calendar lists,
 25	 * for the DI premium as for the quote distance. A negotiated offer retires what adheres, all or
 26	 * part. The reference security of a make-whole must be the nearest in duration among the
 27	 * candidates the base lists, or the route is insufficient evidence.
 28	 */
 29	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 30	const nonEmpty = z.string().trim().min(1);
 31	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 32	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 33	const anchorSchema = z.object({document: nonEmpty, clause: nonEmpty.optional(), page: z.number().int().positive().optional(), note: nonEmpty.optional()}).strict();
 34	type Anchor = z.infer<typeof anchorSchema>;
 35	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 36	
 37	/** A dated amount with its anchor; the base of every price is built from these, never from a default. */
 38	const datedAmountSchema = z.object({value: nonNegative, asOf: isoDate, anchor: anchorSchema}).strict();
 39	const quoteSchema = z.object({
 40	  rate: nonNegative,
 41	  quoteDate: isoDate,
 42	  /** Business days between the quote date and the exit date: the weekdays between them less the holidays the calendar lists. */
 43	  businessDaysBeforeExit: z.number().int().positive(),
 44	  /** Holidays between the quote date and the exit date, from the calendar the base cites (zero must be stated too). */
 45	  holidaysBetween: z.object({count: z.number().int().nonnegative(), anchor: anchorSchema}).strict(),
 46	  security: nonEmpty,
 47	  /** The reference security's own duration in business days, and the candidates the source lists with theirs: the chosen security must be the nearest to the series' duration. */
 48	  securityDurationBusinessDays: z.number().int().positive(),
 49	  candidates: z.array(z.object({security: nonEmpty, durationBusinessDays: z.number().int().positive()}).strict()).min(1),
 50	  anchor: anchorSchema,
 51	}).strict();
 52	/** Business days to maturity: the weekdays between the exit and the maturity less the holidays the calendar lists (zero must be stated too). */
 53	const businessDaysSchema = z.object({count: z.number().int().nonnegative(), maturity: isoDate, holidays: z.object({count: z.number().int().nonnegative(), anchor: anchorSchema}).strict(), anchor: anchorSchema}).strict();
 54	const referenceRateSchema = z.enum(["NTN-B (ANBIMA indicative, nearest duration)", "B3 Pre x DI curve (nearest vertex to remaining duration)"]);
 55	const makeWholeFields = {
 56	  availableFrom: isoDate,
 57	  referenceRate: referenceRateSchema,
 58	  /** The floor the series writes: the updated value (max of A and B) or none (present value only). */
 59	  floor: z.enum(["max_with_base", "present_value_only"]),
 60	  /** The contractual quote day the series writes. */
 61	  quoteDay: z.enum(["prior_business_day", "second_prior_business_day"]),
 62	  /** The quote of that day, when the base holds it. */
 63	  quote: quoteSchema.nullable(),
 64	  anchor: anchorSchema,
 65	};
