 67	export const exitMechanismSchema = z.discriminatedUnion("mechanism", [
 68	  z.object({
 69	    mechanism: z.literal("extraordinary_amortization_di"),
 70	    /** Premium per year as a decimal (0.004 for 0,40%), applied as [(1 + p)^(DU/252) - 1] over the amount retired. */
 71	    premiumPerYear: nonNegative,
 72	    availableFrom: isoDate,
 73	    /** The share of the nominal the indenture lets an amortization retire (0.98 for 98%), and the share this alternative retires. */
 74	    maxFraction: nonNegative,
 75	    fraction: nonNegative,
 76	    businessDays: businessDaysSchema,
 77	    anchor: anchorSchema,
 78	  }).strict(),
 79	  z.object({mechanism: z.literal("total_redemption_di"), premiumPerYear: nonNegative, availableFrom: isoDate, businessDays: businessDaysSchema, anchor: anchorSchema}).strict(),
 80	  z.object({mechanism: z.literal("extraordinary_amortization_ipca"), maxFraction: nonNegative, fraction: nonNegative, ...makeWholeFields}).strict(),
 81	  z.object({mechanism: z.literal("total_redemption_ipca"), ...makeWholeFields}).strict(),
 82	  z.object({mechanism: z.literal("extraordinary_amortization_pre"), maxFraction: nonNegative, fraction: nonNegative, ...makeWholeFields}).strict(),
 83	  z.object({mechanism: z.literal("total_redemption_pre"), ...makeWholeFields}).strict(),
 84	  z.object({
 85	    mechanism: z.literal("negotiated_offer"),
 86	    /** Open since issuance in the 13th, 14th and 15th; the premium is set in the notice and the holders decide; what adheres is retired, all or part. */
 87	    availableFrom: isoDate,
 88	    premium: z.object({rate: nonNegative, anchor: anchorSchema}).strict().nullable(),
 89	    requiresFullAdherence: z.boolean(),
 90	    /** The share of the series that adhered, when a notice and its result are in the base; null before that. */
 91	    adhesion: z.object({fraction: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
 92	    anchor: anchorSchema,
 93	  }).strict(),
 94	  z.object({mechanism: z.literal("acquisition"), availableFrom: isoDate.nullable(), anchor: anchorSchema}).strict(),
 95	]);
 96	const MAKE_WHOLE = new Set(["extraordinary_amortization_ipca", "total_redemption_ipca", "extraordinary_amortization_pre", "total_redemption_pre"]);
 97	const PARTIAL = new Set(["extraordinary_amortization_di", "extraordinary_amortization_ipca", "extraordinary_amortization_pre"]);
 98	
 99	export const exitCostInputSchema = z.object({
100	  exitDate: isoDate,
101	  unit: unitSchema,
102	  /** The documents of the base; every anchor must name one of them, and a mechanism must cite an indenture. */
103	  documents: z.array(z.object({name: nonEmpty, kind: z.enum(["indenture", "itr", "ledger", "quote", "calendar", "notice", "market_data", "other"])}).strict()).min(1),
104	  series: z.array(z.object({
105	    id: nonEmpty,
106	    label: nonEmpty,
107	    /** The indenture that governs the series; without one in the base the series is not priced. */
108	    indenture: z.object({document: nonEmpty, clause: nonEmpty.optional()}).strict().nullable(),
109	    /** Nominal at the exit date (updated where indexed), with the derivation the source allows; null when the base does not hold it. */
110	    nominalAtExit: z.object({value: nonNegative, asOf: isoDate, derivation: z.enum(["unit_value_x_quantity_updated", "unit_value_x_quantity", "ledger_balance_at_exit_date", "trustee_report_at_exit_date"]), anchor: anchorSchema}).strict().nullable(),
111	    /** Remuneration accrued to the exit date; null when the base does not hold it (never zero by default). */
112	    accruedAtExit: datedAmountSchema.nullable(),
113	    /** Charges due at the exit date as the indenture states them, an explicit zero included; null when the base is silent. */
114	    chargesAtExit: datedAmountSchema.nullable(),
115	    /** Remaining flows after the exit date for the make-whole prices, each with its business days from the exit date; null when the base has no schedule. */
116	    remainingFlows: z.array(z.object({id: nonEmpty, date: isoDate, amount: nonNegative, businessDaysFromExit: z.number().int().positive(), anchor: anchorSchema}).strict()).nullable(),
117	    /** The series' own remuneration as an annual rate (the real spread for an IPCA series, the fixed rate for a pre series), which the indenture uses to discount the duration that selects the reference security. */
118	    remunerationRate: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
119	    mechanisms: z.array(exitMechanismSchema),
120	    anchor: anchorSchema,
121	  }).strict()),
122	}).strict().superRefine((input, context) => {
123	  const documents = new Map(input.documents.map((document) => [document.name, document.kind]));
124	  const names = new Set<string>();
125	  input.documents.forEach((document, index) => { if (names.has(document.name)) context.addIssue({code: "custom", path: ["documents", index], message: `duplicate document ${document.name}`}); names.add(document.name); });
126	  const checkAnchor = (anchor: Anchor, path: (string | number)[]) => { if (!documents.has(anchor.document)) context.addIssue({code: "custom", path, message: `anchor names ${anchor.document}, which is not a document of the base`}); };
127	  const ids = new Set<string>();
128	  input.series.forEach((series, index) => {
129	    if (ids.has(series.id)) context.addIssue({code: "custom", path: ["series", index], message: `duplicate series ${series.id}`});
130	    ids.add(series.id);
131	    checkAnchor(series.anchor, ["series", index, "anchor"]);
132	    if (series.indenture && documents.get(series.indenture.document) !== "indenture") context.addIssue({code: "custom", path: ["series", index, "indenture"], message: `${series.id}: ${series.indenture.document} is not registered as an indenture`});
133	    for (const [name, amount] of [["nominalAtExit", series.nominalAtExit], ["accruedAtExit", series.accruedAtExit], ["chargesAtExit", series.chargesAtExit]] as const) {
134	      if (!amount) continue;
135	      checkAnchor(amount.anchor, ["series", index, name, "anchor"]);
136	      if (amount.asOf !== input.exitDate) context.addIssue({code: "custom", path: ["series", index, name], message: `${series.id}: ${name} dated ${amount.asOf} is not the base at the exit date ${input.exitDate}`});
137	    }
138	    const flowIds = new Set<string>();
139	    (series.remainingFlows ?? []).forEach((flow, position) => {
140	      checkAnchor(flow.anchor, ["series", index, "remainingFlows", position, "anchor"]);
141	      if (flowIds.has(flow.id)) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: duplicate flow ${flow.id}`});
142	      flowIds.add(flow.id);
143	      if (flow.date <= input.exitDate) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: flow ${flow.id} on ${flow.date} is not after the exit date`});
144	      if (flow.businessDaysFromExit > weekdaysBetween(input.exitDate, flow.date)) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: flow ${flow.id} claims ${flow.businessDaysFromExit} business days in ${weekdaysBetween(input.exitDate, flow.date)} weekdays`});
145	    });
146	    const kinds = new Set<string>();
147	    series.mechanisms.forEach((mechanism, position) => {
148	      const path = ["series", index, "mechanisms", position];
149	      if (kinds.has(mechanism.mechanism)) context.addIssue({code: "custom", path, message: `${series.id}: mechanism ${mechanism.mechanism} listed twice`});
150	      kinds.add(mechanism.mechanism);
151	      checkAnchor(mechanism.anchor, [...path, "anchor"]);
152	      if (documents.get(mechanism.anchor.document) !== "indenture") context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} must cite an indenture, not ${mechanism.anchor.document}`});
153	      if (series.indenture && mechanism.anchor.document !== series.indenture.document) context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} cites ${mechanism.anchor.document}, not the series' indenture ${series.indenture.document}`});
154	      if (!mechanism.anchor.clause) context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} must cite the clause of the indenture that writes it`});
155	      if ("businessDays" in mechanism) {
156	        checkAnchor(mechanism.businessDays.anchor, [...path, "businessDays", "anchor"]);
157	        checkAnchor(mechanism.businessDays.holidays.anchor, [...path, "businessDays", "holidays"]);
158	        if (documents.get(mechanism.businessDays.anchor.document) !== "calendar" || documents.get(mechanism.businessDays.holidays.anchor.document) !== "calendar") context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: business days and holidays must cite a calendar of the base`});
159	        if (mechanism.businessDays.maturity <= input.exitDate) context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: maturity ${mechanism.businessDays.maturity} is not after the exit date`});
160	        if (mechanism.businessDays.count === 0) context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: a maturity after the exit date has at least one business day; a count of zero prices a premium of zero`});
